insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('b5dd7a92-57a2-5757-8149-b7c8dde76d9a', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'The graph of the function $f$ is shown, where $y = f(x)$. What is the value of $f(0)$?', '["$-6$", "$-4$", "$-3$", "$0$"]'::jsonb, 1, '![figure](/q/nov24/002.webp)'),
  ('0c56ad23-e9e5-5958-9ad1-238fcd5949ab', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'Note: Figure not drawn to scale. In the figure, two lines intersect at a point. If $r = 61$, what is the value of $s$?', '[]'::jsonb, 2, '![figure](/q/nov24/003.webp)'),
  ('db2d11e8-d126-5dc7-88c6-6a4c01e3716d', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'The function $f$ is defined by $f(x) = 5x^{2}$. What is the value of $f(7)$?', '["35", "45", "70", "245"]'::jsonb, 3, null),
  ('c7d0f547-4617-58ee-8c76-7f628c25eb60', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', '$x + 5y = 5$
$x - 5y = 7$
The solution to the given system of equations is $(x,y)$. What is the value of $x$?', '["1.2", "5", "6", "12"]'::jsonb, 4, null),
  ('376f14f6-32b0-577b-a5cb-80510ddd4836', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'Which expression is equivalent to $6x(x + 3)$?', '["$6x^{2} + 3$", "$6x^{2} + 18x$", "$7x^{2} + 3$", "$7x^{2} + 9x$"]'::jsonb, 5, null),
  ('3ac1d09d-a67c-5631-be46-839f7e0ee69c', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'The function $f$ is defined by $f(x) = 3x^{5}$. In the xy-plane, the graph of $y = g(x)$ is the result of shifting the graph of $y = f(x)$ up $9$ units. Which equation defines the function $g$?', '["$g(x) = 3x^{5} + 9$", "$g(x) = 3x^{5} - 9$", "$g(x) = 3x^{45}$", "$g(x) = 27x^{5}$"]'::jsonb, 6, null),
  ('d5f7a7aa-b2e7-55d3-9cc8-1b9eef599fad', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'For the linear function $f$, the graph of $y = f(x)$ in the $xy$-plane has a slope of $69$ and $f(0) = 3$. Which equation defines $f$?', '["$f(x) = 3x$", "$f(x) = 3x + 3$", "$f(x) = 69x$", "$f(x) = 69x + 3$"]'::jsonb, 7, null),
  ('27e9a5d2-0fb2-588f-b67b-b458c95d24f2', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', '5% of $w$ is $741.41$. What is the value of $w$?', '["$778.481$", "$3,707.05$", "$14,828.2$", "$70,433.95$"]'::jsonb, 8, null),
  ('9c4b6b24-174a-54d7-bd2d-1d69c500939e', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'The graph of a system of a linear and a quadratic equation is shown, What system is represented by the graph?', '["$y = -\\frac{7}{16}x^{2}$\n\n$y = -\\frac{7}{4}x$", "$y = -\\frac{7}{16}x^{2}$\n\n$y = \\frac{7}{4}x$", "$y = \\frac{7}{16}x^{2}$\n\n$y = -\\frac{7}{4}x$", "$y = \\frac{7}{16}x^{2}$\n\n$y = \\frac{7}{4}x$"]'::jsonb, 9, '![figure](/q/nov24/004.webp)'),
  ('2e621e48-d17a-5949-9892-221ee995a4b2', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'The function $W$ gives the total time, in minutes, it takes for a gardener to water $x$ plants and mow the grass. According to the function, how many minutes does it take the gardener to mow the grass?
$W(x) = 4x + 80$', '[]'::jsonb, 10, null),
  ('017b501a-3b01-514c-9865-205ace98a982', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', '$19 = x + y$
$x - y = 9$
The solution to the given system of equations is $(x,y)$. What is the value of $x$?', '["$9$", "$10$", "$14$", "$19$"]'::jsonb, 11, null),
  ('db4e71a7-cde4-5124-99eb-50b9bf07529c', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', '$x^{2} - 16x + y^{2} - 10y - 55 = 0$
In the xy-plane, the graph of the given equation is a circle. If this circle is inscribed in a square, what is the perimeter of the square?', '["$24$", "$48$", "$96$", "$220$"]'::jsonb, 12, null),
  ('fb1e9e5c-4fe2-5869-95ca-f35e53041400', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'If $5(3x + 6) = 3(3x + 6) + 78$, what is the value of $3x + 6$?', '["$78$", "$39$", "$33$", "$11$"]'::jsonb, 13, null),
  ('e2b3f1e3-f9e2-56cc-acce-fc3b24f95801', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'If $f(x) = x + 5$ and $g(x) = 5x$, what is the value of $7f(4) - g(4)$?', '["$-11$", "$13$", "$35$", "$43$"]'::jsonb, 14, null),
  ('7e487a45-15bb-511c-9a41-a5b5eff135bc', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'The function $C$ gives the estimated number of cephalopods, a class of marine animal, in a certain area, where $t$ is the number of months since a study began. How many months after the study began was the number of cephalopods in the area estimated to be $247$? The function is given by:
$C(t) = 240(\frac{53}{52})^{t-15}+ 7$', '[]'::jsonb, 15, null),
  ('0a6914ce-602c-5580-9ae7-3095f7ab738a', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'An object moves at a speed of $\frac{3}{17}$ feet per second. What is this speed in yards per second? (3 feet = 1 yard)', '["$\\frac{1}{17}$", "$0.058$", "$0.059$", "$0.0588$"]'::jsonb, 16, null),
  ('56a43802-ecec-5713-8f86-b51531d1de25', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'For the linear function $g$, the table shows four values of $x$ and their corresponding values of $g(x)$. The function can be written as $g(x) = xm + b$, where $m$ and $b$ are constants. What is the value of $b$?', '[]'::jsonb, 17, '| $x$ | $g(x)$ |
| $1$ | $34$ |
| $2$ | $31$ |
| $3$ | $28$ |
| $4$ | $25$ |'),
  ('65b7543c-375e-5a60-9fd8-9d78a1615e69', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'The current value of a house is \$174,000, and this value increases by $2.4%$ each year from the value of the previous year. Which function $f$ gives the value, in dollars, of the house years from now?', '["$f(x) = 174,000(0.024)^{x}$", "$f(x) = 174,000(0.24)^{x}$", "$f(x) = 174,000(1.024)^{x}$", "$f(x) = 174,000(1.24)^{x}$"]'::jsonb, 18, null),
  ('09fe920b-0a36-566c-b06d-779a88a03bab', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'What is the value of $\sin 18π$?', '["$0$", "$\\frac{1}{2}$", "$\\frac{\\sqrt{2}}{2}$", "$1$"]'::jsonb, 19, null),
  ('484b011f-5442-563d-909a-5767d6dc3fca', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'In triangle $QRS$ shown, $QR < RS$. Which expression represents the length of $QS$?', '["$17\\cos Q$", "$17\\sin Q$", "$\\frac{17}{\\cos Q}$", "$\\frac{17}{\\sin Q}$"]'::jsonb, 20, '![figure](/q/nov24/005.webp)'),
  ('8a45e4ee-c30a-5f33-a49e-58426190180a', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', '$\frac{1}{9}x - \frac{3r}{7}y = 34$
One of the equations in a system of two linear equations is given, where $r$ is a nonzero constant. The system has no solution. If the other equation in the system is graphed in the xy-plane, what is the slope of the graph?', '["$-\\frac{27r}{7}$", "$\\frac{27}{7r}$", "$\\frac{7r}{27}$", "$\\frac{7}{27r}$"]'::jsonb, 21, null),
  ('4be5f663-c228-5188-8c77-75c3894478bd', '660dcd01-0f04-5823-8a31-5f6e0bd894d7', 'A machine makes 8-inch, 9-inch, and 3-inch parts. During a certain day, the number of 8-inch parts that the machine makes is 4 times the number $n$ of 9-inch parts, and the number of 3-inch parts is 30. During this day, the machine makes 100 parts total. Which equation represents this situation?', '["$8(4n) + 9n + 3(30) = 100$", "$8n + 9n + 3n = 100$", "$4n + 30 = 100$", "$5n + 30 = 100$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('b5dd7a92-57a2-5757-8149-b7c8dde76d9a', 0, null, '**Choice A is correct.** The value $f(0)$ is the y-coordinate of the point on the graph where $x = 0$, i.e., the y‑intercept. Reading the graph at the vertical axis ($x = 0$) shows the curve crossing at $y = -6$, so $f(0) = -6$.
**Choice B is incorrect.** $y = -4$ is two units above the actual intercept; the graph at $x = 0$ is lower, at $-6$, not $-4$.
**Choice C is incorrect.** $y = -3$ is three units above the true intercept; the plotted curve at $x = 0$ is at $-6$, not $-3$.
**Choice D is incorrect.** $y = 0$ would place the intercept on the x‑axis, but the graph clearly crosses the vertical axis at a negative value ($-6$), not at 0.
**Faster approach:** Directly read the y‑coordinate where the graph crosses the vertical axis (the y‑intercept) — that value is $f(0)$.'),
  ('0c56ad23-e9e5-5958-9ad1-238fcd5949ab', null, array['61']::text[], '**The correct answer is 61.** When two lines intersect they form two pairs of vertical angles; each pair consists of opposite (nonadjacent) angles that are congruent. The angles labeled $r$ and $s$ are opposite each other in the figure, so $s = r$.
Given $r = 61°$, substituting gives $s = 61°$.
**Faster approach:** Immediately check whether the marked angles are vertical (opposite) or a linear pair (adjacent). If vertical, set $s = r$ and substitute the given value; if adjacent, use $s = 180° - r$. Here they are vertical, so $s = 61°$.'),
  ('db2d11e8-d126-5dc7-88c6-6a4c01e3716d', 3, null, '**Choice D is correct.** The definition gives $f(x) = 5x^{2}$, so $f(7) = 5 \cdot 7^{2} = 5 \cdot 49 = 245.$
**Choice A is incorrect.** 35 equals $5 \cdot 7$, not $5 \cdot 7^{2}$, so it omits the squaring of 7.
**Choice B is incorrect.** 45 does not equal $5 \cdot 7^{2}$; it appears to be $9 \cdot 5$ or another unrelated product.
**Choice C is incorrect.** 70 equals $10 \cdot 7$ or $5 \cdot 14$, not $5 \cdot 49$, so it is also not the correct value.
**Faster approach:** Evaluate the power first ($7^{2} = 49$), then multiply by 5 to get 245; for any $f(x) = ax^{2}$, compute $x^{2}$ before multiplying by $a$.'),
  ('c7d0f547-4617-58ee-8c76-7f628c25eb60', 2, null, '**Choice C is correct.** Add the two equations to eliminate $y$: $(x + 5y) + (x - 5y) = 5 + 7$, so $2x = 12$ and $x =$ $6$. Thus the solution has $x = 6$, which matches choice C.
**Choice A is incorrect.** $x = 1.2$ would make $2x = 2.4$, which does not equal $12$, so it cannot satisfy the sum of the two equations.
**Choice B is incorrect.** $x = 5$ gives $2x = 10$, not $12$, so the equations would not both be satisfied.
**Choice D is incorrect.** $x = 12$ gives $2x = 24$, which is inconsistent with the required $2x = 12$ from adding the equations.
**Faster approach:** For linear systems with opposite coefficients on one variable, add (or subtract) the equations to eliminate that variable immediately and solve for the other variable.'),
  ('376f14f6-32b0-577b-a5cb-80510ddd4836', 1, null, '**Choice B is correct.** Multiply $6x$ by each term in the parentheses: $6x(x + 3) = 6x \cdot x + 6x \cdot 3 = 6x^{2} + 18x$, which matches Choice B.
**Choice A is incorrect.** $6x^{2} + 3$ would result from $6x^{2} + (+3)$, but distributing $6x$ to $3$ gives $18x$, not $3$; the constant term shown is wrong and a term in $x$ is missing.
**Choice C is incorrect.** $7x^{2} + 3$ has the wrong coefficients: distributing yields $6x^{2} + 18x$, not $7x^{2} + 3$, so both the $x^{2}$ coefficient and the other terms are incorrect.
**Choice D is incorrect.** $7x^{2} + 9x$ also has incorrect coefficients: neither the $x^{2}$ coefficient nor the $x$ coefficient match the expansion $6x^{2} + 18x$.
**Faster approach:** Use the distributive property once: multiply $6x$ by each term inside $(x + 3)$ to get $6x^{2}$ and $18x$ directly.'),
  ('3ac1d09d-a67c-5631-be46-839f7e0ee69c', 0, null, '**Choice A is correct.** A vertical shift up by 9 units adds 9 to the function values, so $g(x) = f(x) + 9 = 3x^{5} + 9$ , which matches choice A.
**Choice B is incorrect.** Subtracting 9 would shift the graph down 9 units, not up.
**Choice C is incorrect.** $3x^{45}$ changes the exponent and is not obtained by a vertical shift; it also is not equivalent to $3x^{5} + 9$.
**Choice D is incorrect.** $27x^{5}$ multiplies the function by 9 (a vertical stretch), not translate it up; it does not represent a shift of 9 units upward.
**Faster approach:** For any function, a vertical shift up by k units produces $g(x) = f(x) + k$. Immediately add 9 to $3x^{5}$ to get the answer.'),
  ('d5f7a7aa-b2e7-55d3-9cc8-1b9eef599fad', 3, null, '**Choice D is correct.** A linear function in slope-intercept form is $f(x) = mx + b$, where $m$ is the slope and $b =$ $f(0)$ is the $y$-intercept. Here the slope is $69$ and $f(0) = 3$, so $m = 69$ and $b = 3$, giving $f(x) = 69x + 3$, which matches Choice D.
**Choice A is incorrect.** $f(x) = 3x$ has slope $3$ and intercept $0$, not slope $69$ or $f(0) = 3$.
**Choice B is incorrect.** $f(x) = 3x + 3$ has slope $3$, not $69$, so it does not match the given slope.
**Choice C is incorrect.** $f(x) = 69x$ has the correct slope but has $f(0) = 0$, not $3$, so it does not satisfy the given intercept.
**Faster approach:** Immediately use slope-intercept form $f(x) = mx + b$, plug $m = 69$ and $b = f(0) = 3$ to get $69x + 3$ and select the matching choice.'),
  ('27e9a5d2-0fb2-588f-b67b-b458c95d24f2', 2, null, '**Choice C is correct.** If 5% of $w$ equals $741.41$, then $0.05w = 741.41$, so $w = 741.41/0.05$. Dividing by $0.05$ is equivalent to multiplying by $20$, giving $w = 741.41 \times 20 = 14,828.2$, which matches Choice C.
**Choice A is incorrect.** $778.481$ is far too small; it would make 5% equal to about $38.92$, not $741.41$.
**Choice B is incorrect.** $3,707.05$ is also too small; 5% of that is about $185.35$, not $741.41$.
**Choice D is incorrect.** $70,433.95$ is much too large; 5% of that is about $3,521.70$, not $741.41$.
**Faster approach:** Divide the given amount by 0.05 (or multiply by 20) to undo the "5% of" operation and get $w$ directly.'),
  ('9c4b6b24-174a-54d7-bd2d-1d69c500939e', 3, null, '**Choice D is correct.** The graph shows a parabola opening upward, so the quadratic coefficient must be positive, eliminating A and B. The straight line slopes upward left-to-right, so its slope is positive. Choice D gives $y = \frac{7}{16}x^{2}$ and $y = \frac{7}{4}x$. Setting them equal: $\frac{7}{16}x^{2} = \frac{7}{4}x$; dividing by $7$ and multiplying by $16$ gives $x^{2} = 4x$, so $x(x - 4) = 0$, intersections at $x = 0$ and $x = 4$, which match the graph’s intersection at the origin and the point to the right.
**Choice C is incorrect.** Although the quadratic is positive, the line in C has negative slope; the graph’s line slopes upward, not downward.
**Choice A is incorrect.** A has a downward-opening parabola (negative quadratic coefficient), but the graph opens upward.
**Choice B is incorrect.** B also has a downward-opening parabola, so it contradicts the graph.
**Faster approach:** First check opening direction of the parabola (sign of quadratic coefficient) to eliminate two choices, then check the sign of the line’s slope by its left-to-right tilt to pick between the remaining two.'),
  ('2e621e48-d17a-5949-9892-221ee995a4b2', null, array['80']::text[], '**The correct answer is 80.** The function $W(x) = 4x + 80$ gives total time as the sum of time that depends on the number of plants and a fixed time. The term $4x$ varies with $x$ (it represents $4$ minutes per plant), while the constant term $80$ represents the time that does not depend on $x$. Therefore the mowing time — the fixed portion of the total — is $80$ minutes.
**Faster approach:** Identify the constant term in the linear expression $ax + b$: $b$ is the fixed time (mowing), so read off $80$ immediately.'),
  ('017b501a-3b01-514c-9865-205ace98a982', 2, null, '**Choice C is correct.** To solve the system of equations given by
$19 = x + y$
and
$x - y = 9$
, we can use substitution or elimination. Here, I will use the elimination method.
First, let’s solve for $y$ in terms of $x$ using the first equation:
From
$19 = x + y$
, we can express $y$ as
$y = 19 - x$
.
Next, we''ll substitute this expression for $y$ into the second equation:
Substituting into
$x - y = 9$
gives us:
$x - (19 - x) = 9$
.
This simplifies to
$x - 19 + x = 9$
.
Combining like terms, we have
$2x - 19 = 9$
.
To solve for $x$, add $19$ to both sides:
$2x = 28$
.
Dividing by $2$, we find
$x = 14$
.
Now that we have found that
$x = 14$
Using $y = 19 - x$, we find
$y = 19 - 14 = 5$
.
We can check our solution by substituting $x$ and $y$ into the second equation:
$14 - 5 = 9$
, which is true.
Thus, the value of $x$ is indeed
$14$
, making Choice C the correct answer.
Now, let’s briefly analyze the other options:
**Choice A (** $9$**):** If $x = 9$, then $y = 19 - 9 = 10$. Substituting into the second equation gives
$9 - 10 \ne 9$
, so this is incorrect.
**Choice B (** $10$**):** If $x = 10$, then $y = 19 - 10 = 9$. Substituting into the second equation gives
$10 - 9 \ne 9$
, so this is incorrect.
**Choice D (** $19$**):** If $x = 19$, then $y = 19 - 19 = 0$. Substituting into the second equation gives
$19 - 0 \ne 9$
, so this is also incorrect.'),
  ('db4e71a7-cde4-5124-99eb-50b9bf07529c', 2, null, '**Choice C is correct.** Complete the square: $x^{2} - 16x = (x - 8)^{2} - 64$ and $y^{2} - 10y = (y - 5)^{2} - 25$. Substituting gives $(x - 8)^{2} + (y - 5)^{2} - 64 - 25 - 55 = 0$, so $(x - 8)^{2} + (y - 5)^{2} = 144$. Thus the circle has radius $r = 12$. A circle inscribed in a square has side length equal to the circle’s diameter $2r = 24$, so the perimeter is $4 \cdot 24 = 96$, choice C.
**Choice A is incorrect.** 24 is the side length of the square, not the perimeter; the question asks for perimeter.
**Choice B is incorrect.** 48 equals twice the side length (or four times the radius), not the full perimeter; it does not match $4 \cdot (2r)$.
**Choice D is incorrect.** 220 is far too large given the radius $12$; it does not follow from $4 \cdot (2r) = 96$.
**Faster approach:** Complete the square to get $r$ quickly, note that side length = diameter $= 2r$, then perimeter $= 4(2r) = 8r$. So find $r$ and multiply by 8.'),
  ('fb1e9e5c-4fe2-5869-95ca-f35e53041400', 1, null, '**Choice B is correct.** Let $y = 3x + 6$. The equation becomes $5y = 3y + 78$, so $2y = 78$ and $y = 39$. Thus $3x +$ $6 = 39$, which matches choice B.
**Choice A is incorrect.** If $3x + 6$ were $78$, substituting gives $5(78) = 3(78) + 78$, or $390 = 312 + 78 = 390$, which actually does hold; however, this corresponds to $y = 78$ which does not satisfy the simplified linear step $2y = 78$ (that yields $y = 39$). The apparent arithmetic check shows the left and right would match only if the algebraic reduction were different; therefore A is not the solution of the original equation.
**Choice C is incorrect.** Substituting $y = 33$ into $5y = 3y + 78$ gives $165 = 99 + 78 = 177$, which is false.
**Choice D is incorrect.** Substituting $y = 11$ gives $55 = 33 + 78 = 111$, which is false.
**Faster approach:** Immediately set $y = 3x + 6$ to reduce the equation to $5y = 3y + 78$, solve $2y = 78$, and get $y = 39$—a one-step substitution that works for any similar linear-expression-in-a-linear-equation problem.'),
  ('e2b3f1e3-f9e2-56cc-acce-fc3b24f95801', 3, null, '**Choice D is correct.** Evaluate each function at $x = 4$: $f(4) = 4 + 5 = 9$ and $g(4) = 5 \cdot 4 = 20$. Then compute $7f(4) - g(4) = 7 \cdot 9 - 20 = 63 - 20 = 43$, which matches choice D.
**Choice A is incorrect.** $-11$ would correspond to $63 - 74$ or some other mistaken subtraction; it does not match the correct values $7 \cdot 9 - 20 = 43$.
**Choice B is incorrect.** $13$ is far too small; it would result from $33 - 20$ or miscomputing $7f(4)$ as $33$ instead of $63$.
**Choice C is incorrect.** $35$ equals $7 \cdot 5$ or $63 - 28$, which reflects miscalculating either $f(4)$ or $g(4)$; it does not equal $7 \cdot 9 - 20$.
**Faster approach:** Evaluate $f(4)$ and $g(4)$ mentally ($9$ and $20$), then do the single subtraction $63 - 20 = 43$. This direct-evaluate-then-compute method works for all similar function-computation problems.'),
  ('7e487a45-15bb-511c-9a41-a5b5eff135bc', null, array['15']::text[], '**The correct answer is 15.** Start with the equation $C(t) = 247$, so $240(\frac{53}{52})^{t-15} + 7 = 247$. Subtract 7 from both sides to get $240(\frac{53}{52})^{t-15} = 240$. Divide both sides by 240 to obtain $(\frac{53}{52})^{t-15} = 1$. Because the base $\frac{53}{52}$ is positive and not equal to 1, the only way a positive base raised to an exponent equals 1 is when the exponent is 0; thus $t - 15 = 0$, so $t = 15$.
**Faster approach:** Immediately subtract 7 and divide by 240 to see the exponential equals 1, which implies the exponent is 0, so read off $t = 15$ without additional algebra.'),
  ('0a6914ce-602c-5580-9ae7-3095f7ab738a', 2, null, '**Choice C is correct.** To convert the speed from feet per second to yards per second, we can use the conversion factor that 1 yard equals 3 feet.
Starting with the speed of the object:
The speed in feet per second is given as:
$\frac{3}{17}$ feet/second.
To convert this speed into yards per second, we apply the conversion factor:
1 yard = 3 feet, so we divide the speed by 3:
Speed in yards per second = $\frac{3/17}{3} = \frac{3}{17\times 3} = \frac{3}{51}$.
Simplifying $\frac{3}{51}$ gives us:
$\frac{3}{51} = \frac{1}{17}$
.
Now we will convert $\frac{1}{17}$ into a decimal to compare with the answer choices:
Calculating $\frac{1}{17} \approx 0.0588235$, which rounds to 0.059.
Thus, the correct conversion results in approximately $0.059$, which corresponds to:
**C)** $0.059$, therefore it is the correct answer.
Now, let’s briefly discuss the other options:
**A)** $\frac{1}{17}$ is equivalent to $0.0588235$, which is not provided in the options and does not match the rounding. **B)** $0.058$ reflects a rounding down of our calculated answer, which overlooks the proper rounding based on significant figures.
**D)** $0.0588$ is also incorrect as it does not match the calculated value of $0.059$.
Therefore, the best choice is indeed C) $0.059$.'),
  ('56a43802-ecec-5713-8f86-b51531d1de25', null, array['37']::text[], '**The correct answer is 37.** The outputs decrease by 3 for each increase of 1 in $x$, so the slope is $m = -3$. Write $g(x) = -3x + b$. Substitute a known point, for example $(1,34)$: $34 = -3(1) + b$, so $34 = -3 + b$ and $b = 34 +$ $3 = 37$.
**Faster approach:** Recognize successive outputs 34, 31, 28, 25 show a constant change of $-3$, so $g(x) =$ $-3x + b$; add 3 to the value at $x = 1$ to get $b = 37$ (or compute $b = g(x) + 3x$ using any table row).'),
  ('65b7543c-375e-5a60-9fd8-9d78a1615e69', 2, null, '**Choice C is correct.** The house increases by 2.4% each year, so each year its value is multiplied by $1 +$ $0.024 = 1.024$. After $x$ years the value is the initial amount times the growth factor to the $x$th power, so $f(x) = 174000(1.024)^{x}$.
**Choice A is incorrect.** $0.024$ is the decimal representation of the rate but using $(0.024)^{x}$ would represent repeated multiplication by $2.4%$, which models drastic decay, not growth.
**Choice B is incorrect.** $(0.24)^{x}$ uses $24%$ (0.24) rather than $2.4%$ (0.024), and also would model repeated multiplication by 0.24 (large decay), not 1.024 growth.
**Choice D is incorrect.** $(1.24)^{x}$ corresponds to a $24%$ annual increase, not the given $2.4%$ increase.
**Faster approach:** For a percent increase r%, use factor $1 + r/100$; here $1 + 2.4/100 = 1.024$, so pick $174000(1.024)^{x}$.'),
  ('09fe920b-0a36-566c-b06d-779a88a03bab', 0, null, '**Choice A is correct.** The sine function has period $2π$, so $\sin (18π) = \sin (18π - 9 \cdot 2π) = \sin (0) = 0$. Also, for any integer $n$, $\sin (nπ) = 0$, and $18π$ is an integer multiple of $π$, so the value is $0$.
**Choice B is incorrect.** $\frac{1}{2}$ is the sine of angles like $π/6$ or $5π/6$, not of an integer multiple of $π$ such as $18π$. **Choice C is incorrect.** $\frac{\sqrt{2}}{2}$ equals $\sin (π/4)$ or $\sin (3π/4)$, not $\sin (18π)$, and it is nonzero while $\sin (18π) = 0$. **Choice D is incorrect.** $1$ is the sine of $π/2$ (or odd multiples thereof), but $18π$ is not such an angle; since $18π$ is a whole multiple of $π$, its sine is $0$, not $1$.
**Faster approach:** Recognize that $\sin (nπ) = 0$ for any integer $n$ (or reduce the angle modulo $2π$), so any integer multiple of $π$ immediately gives $0$.'),
  ('484b011f-5442-563d-909a-5767d6dc3fca', 3, null, '**Choice D is correct.** In the diagram the right angle is at R and the side RS (the horizontal side opposite angle Q) is labeled 17, so the side opposite angle Q has length 17. In a right triangle $\sin Q = \frac{\text{opposite}}{\text{hypotenuse}} = \frac{17}{QS}$. Solving for $QS$ gives $QS = \frac{17}{\sin Q}$, which is choice D.
**Choice A is incorrect.** $17\cos Q$ would equal the adjacent side to angle Q, but the given 17 is the opposite side, not the adjacent one, so this expression does not produce the hypotenuse $QS$.
**Choice B is incorrect.** $17\sin Q$ equals $(\text{opposite}) \cdot \sin Q$, which does not isolate the hypotenuse; substituting $\sin Q = 17/QS$ gives $17\sin Q = 17 \cdot \frac{17}{QS} = \frac{289}{QS}$, not $QS$.
**Choice C is incorrect.** $\frac{17}{\cos Q}$ would be correct if 17 were the adjacent side to angle Q (since $\cos Q = \frac{\text{adjacent}}{\text{hypotenuse}}$ ). Here 17 is the opposite side, so this ratio is not $QS$.
**Faster approach:** In any right triangle, identify which labeled side is opposite the given angle. If the labeled side is opposite, use $\sin$ to write $\sin (\text{angle}) = \frac{\text{given}}{\text{hypotenuse}}$ and solve for the hypotenuse; if it’s adjacent, use $\cos$ instead. This directly yields the correct reciprocal form for the hypotenuse.'),
  ('8a45e4ee-c30a-5f33-a49e-58426190180a', 3, null, '**Choice D is correct.** For the system to have no solution the two lines must be parallel, so the other line must have the same slope as the given line. Solve the given equation for $y$: $\frac{1}{9}x - \frac{3r}{7}y = 34 ⇒ -\frac{3r}{7}y = 34 - \frac{1}{9}x ⇒$ $y = \frac{\frac{1}{9}x-34}{\frac{3r}{7}}$. The slope is $\frac{1/9}{3r/7} = (1/9) \cdot (7/(3r)) = \frac{7}{27r}$.
**Choice A is incorrect.** $-\frac{27r}{7}$ is the negative reciprocal of the correct slope when multiplied incorrectly by $r$; it does not equal the slope calculated from isolating $y$.
**Choice B is incorrect.** $\frac{27}{7r}$ is the reciprocal of the correct slope (and not the slope itself).
**Choice C is incorrect.** $\frac{7r}{27}$ multiplies by $r$ instead of dividing by $r$; it is not the slope obtained from $y$ in terms of $x$.
**Faster approach:** Put the given equation in slope-intercept form by isolating the $x$-coefficient over the $y$- coefficient: slope = $(1/9)/(3r/7) = (1/9) \cdot (7/(3r))$, which immediately yields $\frac{7}{27r}$ for every such problem.'),
  ('4be5f663-c228-5188-8c77-75c3894478bd', 3, null, '**Choice D is correct.** Let $n$ be the number of 9-inch parts. The number of 8-inch parts is $4n$, and the number of 3-inch parts is $30$. The total number of parts is $4n + n + 30$, which equals $100$, so the equation is $5n + 30 =$ $100$.
**Choice A is incorrect.** That equation multiplies the counts by the part lengths (e.g., $8(4n)$), giving a sum of inches rather than a count of parts; the problem asks about the number of parts, not total inches.
**Choice B is incorrect.** That assumes the machine makes $n$ parts of each size (so $8n + 9n + 3n$), which contradicts the statement that there are $4n$ 8-inch parts and 30 three-inch parts.
**Choice C is incorrect.** That equation omits the $n$ 9-inch parts (it has $4n + 30 = 100$), so it doesn’t account for the single group of $n$ parts.
**Faster approach:** Translate directly to counts: total = (8-inch count) + (9-inch count) + (3-inch count) = $4n + n + 30$, so write $5n + 30 = 100$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

